// A segment divided internally in the ratio 3:1.
// Two-argument size call fixes the output box, so the declared 2 is exact.
size(320,160);
pair A=(0,0), B=(6,0), P=(4.5,0);
draw(A--B,Arrow);
dot(A, black+2.5pt);
dot(B, black+2.5pt);
dot(P, black+3.5pt);
label("$A=(-8,2)$",A,SW);
label("$B=(8,6)$",B,SE);
label("$P$",P,N);
label("$\frac{3}{4}$",(2.25,0),N);
label("$\frac{1}{4}$",(5.25,0),N);
label("measured from $A$",(3,-1),S);
